"""Library removal through actual HTTP; generated bytes, no model calls."""
import importlib.util
import json
from pathlib import Path
import sqlite3
import sys
import threading
import unittest
from urllib.parse import urlencode

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
import test_upload as fixture
from strokesense import web
from strokesense.registry import list_clips, register_clip, revoke_clip


class LibraryRemovalTests(unittest.TestCase):
    request = fixture.UploadHTTPTests.request
    upload = fixture.UploadHTTPTests.upload
    stop = fixture.UploadHTTPTests.stop

    def setUp(self):
        # Before implementation, exercise the unchanged server and observe 404s.
        if importlib.util.find_spec('strokesense.library'):
            from strokesense.library import create_server
        else:
            create_server = web.create_server
        from unittest.mock import patch
        with patch.object(fixture, 'create_server', create_server):
            fixture.UploadHTTPTests.setUp(self)
        self.assertEqual(self.upload()[0], 303)
        self.clip = list_clips(self.db, show_paths=True)[0]
        self.clip_id = self.clip['clip_id']
        self.source = Path(self.clip['source_path'])

    def remove(self, *, fields=None, headers=None):
        form = {'csrf': self.server.csrf_token, 'clip_id': self.clip_id,
                'confirm': 'remove'} if fields is None else fields
        return self.request('POST', '/library/remove', urlencode(form, doseq=True).encode(),
                            'application/x-www-form-urlencoded', headers=headers)

    def test_denied_and_unverified_clips_are_visible_without_private_media(self):
        revoke_clip(self.clip_id, self.db)
        other = self.root / 'not-public.mov'; other.write_bytes(b'other private bytes')
        unknown = register_clip(other, self.db)[0]
        code, headers, body = self.request('GET', '/library')
        self.assertEqual(code, 200)
        for text in (b'Manage video library', b'Denied', b'Unverified',
                     self.clip_id.encode(), unknown['clip_id'].encode()):
            self.assertIn(text, body)
        self.assertNotIn(b'/select?clip=' + self.clip_id.encode(), body)
        self.assertNotIn(b'<img', body)
        self.assertNotIn(str(self.root).encode(), body)
        self.assertNotIn(b'synthetic local attestation', body)
        self.assertEqual(headers['Cache-Control'], 'no-store')
        self.assertIn(b'href="/library"', self.request('GET', '/')[2])

    def test_confirmation_get_and_cancel_never_remove_data(self):
        code, _, body = self.request('GET', '/library/remove?clip=' + self.clip_id)
        self.assertEqual(code, 200)
        self.assertIn(b'Confirm removal', body)
        self.assertIn(b'name="confirm"', body)
        self.assertIn(b'not deleted', body)
        self.assertIn(b'Cancel', body)
        self.assertEqual(len(list_clips(self.db)), 1)
        self.assertTrue(self.source.exists())

    def test_remove_denied_upload_then_reimport_does_not_restore_old_job(self):
        job = self.worker.submit(self.clip_id)
        self.worker.wait(job['job_id'], timeout=3)
        artifact = self.worker._results_root / job['job_id'] / 'keep.txt'
        artifact.write_text('retained generated artifact')
        revoke_clip(self.clip_id, self.db)
        code, headers, _ = self.remove()
        self.assertEqual(code, 303)
        self.assertEqual(headers['Location'], '/library?removed=1')
        self.assertEqual(list_clips(self.db), [])
        self.assertFalse(self.source.exists())
        self.assertIsNone(self.worker.get(job['job_id']))
        self.assertTrue(artifact.exists())
        self.assertEqual(self.upload(provenance='new explicit permission claim')[0], 303)
        self.assertEqual(len(list_clips(self.db)), 1)
        self.assertEqual(self.request('GET', '/jobs/' + job['job_id'])[0], 404)
        self.assertEqual(self.request('GET', '/reports/' + job['job_id'])[0], 404)
        self.assertEqual(self.worker.list_recent(), [])

    def test_original_external_file_and_unrelated_clip_are_preserved(self):
        external = self.root / 'original.mp4'; external.write_bytes(b'original private recording')
        record = register_clip(external, self.db, permission='granted', provenance='original')[0]
        self.clip_id = record['clip_id']
        self.assertEqual(self.remove()[0], 303)
        self.assertEqual(external.read_bytes(), b'original private recording')
        self.assertTrue(self.source.exists())
        self.assertEqual(len(list_clips(self.db)), 1)

    def test_missing_source_can_be_removed_without_touching_other_files(self):
        self.source.unlink()
        marker = self.uploads / 'unrelated.txt'; marker.write_text('keep')
        self.assertEqual(self.remove()[0], 303)
        self.assertTrue(marker.exists())
        self.assertEqual(list_clips(self.db), [])

    def test_confirmation_csrf_and_origin_are_required(self):
        good = {'csrf': self.server.csrf_token, 'clip_id': self.clip_id, 'confirm': 'remove'}
        cases = [({k:v for k,v in good.items() if k != 'confirm'}, None, 400),
                 (dict(good, confirm='no'), None, 422),
                 (dict(good, csrf='forged'), None, 403),
                 (good, {'Origin': 'https://foreign.invalid'}, 403),
                 (good, {'Host': 'foreign.invalid'}, 403),
                 (dict(good, clip_id='../secret'), None, 400),
                 (dict(good, clip_id='f'*64), None, 404),
                 (dict(good, clip_id=[self.clip_id,self.clip_id]), None, 400)]
        for fields, headers, expected in cases:
            with self.subTest(expected=expected, fields=fields):
                self.assertEqual(self.remove(fields=fields, headers=headers)[0], expected)
        self.assertTrue(self.source.exists())
        self.assertEqual(len(list_clips(self.db)), 1)

    def test_active_analysis_blocks_removal(self):
        release = threading.Event(); started = threading.Event()
        self.addCleanup(release.set)
        def waiting(*args, **kwargs):
            started.set(); release.wait(3); return None
        self.worker._analyze_fn = waiting
        job = self.worker.submit(self.clip_id); self.assertTrue(started.wait(1))
        try:
            code, _, body = self.remove()
            self.assertEqual(code, 409)
            self.assertIn(b'queued or running', body)
            self.assertTrue(self.source.exists())
        finally:
            release.set(); self.worker.wait(job['job_id'], timeout=3)

    def test_changed_managed_upload_fails_closed(self):
        self.source.write_bytes(b'changed source must not be erased')
        code, _, _ = self.remove()
        self.assertEqual(code, 409)
        self.assertEqual(self.source.read_bytes(), b'changed source must not be erased')
        self.assertEqual(len(list_clips(self.db)), 1)

    def test_managed_symlink_cannot_delete_external_target(self):
        target = self.root / 'do-not-delete.mov'; target.write_bytes(b'private target')
        self.source.unlink()
        try:
            self.source.symlink_to(target)
        except (OSError, NotImplementedError):
            self.skipTest('symlink unavailable on this platform')
        self.assertEqual(self.remove()[0], 409)
        self.assertEqual(target.read_bytes(), b'private target')
        self.assertEqual(len(list_clips(self.db)), 1)

    def test_empty_library_and_bad_queries_are_clear(self):
        self.assertEqual(self.remove()[0], 303)
        code, _, body = self.request('GET', '/library')
        self.assertEqual(code, 200); self.assertIn(b'Your library is empty', body)
        for query in ('', '?clip=bad', '?clip='+self.clip_id+'&clip='+self.clip_id):
            self.assertEqual(self.request('GET', '/library/remove'+query)[0], 400)
        self.assertEqual(self.request('GET','/library/remove?clip='+self.clip_id)[0],404)


if __name__ == '__main__':
    unittest.main()
